import{_ as s,o as a,c as t,a3 as i}from"./chunks/framework.CWpttWmj.js";const k=JSON.parse('{"title":"Records & profile","description":"","frontmatter":{},"headers":[],"relativePath":"guide/records.md","filePath":"guide/records.md","lastUpdated":1785888355000}'),r={name:"guide/records.md"};function n(o,e,h,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="records-profile" tabindex="-1">Records &amp; profile <a class="header-anchor" href="#records-profile" aria-label="Permalink to &quot;Records &amp; profile&quot;">​</a></h1><p>Records are the data attached to your name — the address it points at, your avatar, your website, your social handles. They live on the <strong>resolver</strong> contract and anyone can read them without permission.</p><h2 id="where-records-live" tabindex="-1">Where records live <a class="header-anchor" href="#where-records-live" aria-label="Permalink to &quot;Where records live&quot;">​</a></h2><p>Records are stored per <strong>node</strong> (the namehash of your name) on a resolver contract, and the registry records which resolver answers for your name. Reading a record is therefore always two steps: find the resolver, then ask it. See <a href="/docs/protocol/resolving.html">Resolving .arc</a>.</p><h2 id="who-is-allowed-to-write" tabindex="-1">Who is allowed to write <a class="header-anchor" href="#who-is-allowed-to-write" aria-label="Permalink to &quot;Who is allowed to write&quot;">​</a></h2><p>This is the part that surprises people. The resolver authorises writes against the <strong>registry owner</strong> of the node, not the holder of the NFT:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">modifier</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes32</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> node</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> o </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ens.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(node);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(o </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> msg.sender</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ens.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isApprovedForAll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(o, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;!auth&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    _</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>For a name you registered yourself these are the same address, because the controller calls <code>reclaim</code> for you at mint time.</p><div class="warning custom-block"><p class="custom-block-title">After a transfer, records are locked until you reclaim</p><p>Receiving the NFT does <strong>not</strong> make you the registry owner. Until the new holder calls <code>registrar.reclaim(tokenId, newOwner)</code>, record writes revert with <code>!auth</code> — and the <em>previous</em> owner can still change them.</p><p>Always reclaim immediately after receiving a name. See <a href="/docs/guide/ownership.html#reclaiming-after-a-transfer">Ownership &amp; transfers</a>.</p></div><h2 id="the-record-types" tabindex="-1">The record types <a class="header-anchor" href="#the-record-types" aria-label="Permalink to &quot;The record types&quot;">​</a></h2><h3 id="address" tabindex="-1">Address <a class="header-anchor" href="#address" aria-label="Permalink to &quot;Address&quot;">​</a></h3><p>The address the name resolves to. This is what a wallet uses when someone sends to <code>alice.arc</code>.</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setAddr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node) → </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span></span></code></pre></div><p>Set for you at registration, pointing at the registrant. Change it whenever you like — that indirection is the main reason to have a name at all.</p><p>An unset address record reads as the zero address. Never send to it.</p><p>There is also a multi-coin form, <code>setAddr(node, coinType, bytes)</code>, for pointing a name at addresses on other chains. The app doesn&#39;t expose it; integrators can use it directly.</p><h3 id="text-records" tabindex="-1">Text records <a class="header-anchor" href="#text-records" aria-label="Permalink to &quot;Text records&quot;">​</a></h3><p>Free-form key/value strings. The app surfaces six:</p><table tabindex="0"><thead><tr><th>Key</th><th>Shown as</th><th>Notes</th></tr></thead><tbody><tr><td><code>description</code></td><td>Description</td><td>Short bio.</td></tr><tr><td><code>url</code></td><td>Website</td><td>Include the scheme: <code>https://…</code>.</td></tr><tr><td><code>avatar</code></td><td>Avatar URL</td><td>An image URL.</td></tr><tr><td><code>com.twitter</code></td><td>X / Twitter</td><td>Handle, without the <code>@</code>.</td></tr><tr><td><code>com.github</code></td><td>GitHub</td><td>Username.</td></tr><tr><td><code>email</code></td><td>Email</td><td>Public — expect scraping.</td></tr></tbody></table><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setText</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> key, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> key) → </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span></span></code></pre></div><p>The keys are a convention, not a restriction — the resolver accepts any key, so an integration can define its own namespaced keys. Reading an unset key returns an empty string.</p><h3 id="contenthash" tabindex="-1">Contenthash <a class="header-anchor" href="#contenthash" aria-label="Permalink to &quot;Contenthash&quot;">​</a></h3><p>For pointing a name at content on a distributed store such as IPFS.</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setContenthash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> hash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">contenthash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node) → </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes</span></span></code></pre></div><p>Not exposed in the app; available on the contract.</p><h3 id="name-the-reverse-record" tabindex="-1">Name (the reverse record) <a class="header-anchor" href="#name-the-reverse-record" aria-label="Permalink to &quot;Name (the reverse record)&quot;">​</a></h3><p><code>setName</code> is used on the <em>reverse</em> node, not on your name&#39;s node, and is how a primary name is set. See <a href="/docs/guide/primary-name.html">Your primary name</a>.</p><h2 id="editing-records-in-the-app" tabindex="-1">Editing records in the app <a class="header-anchor" href="#editing-records-in-the-app" aria-label="Permalink to &quot;Editing records in the app&quot;">​</a></h2><p><strong>My names → the name → Records.</strong></p><p>Each field has its own <strong>Save</strong> button and each save is a separate transaction — changing your avatar and your website means two transactions and two gas fees. The Save button stays disabled until you actually change the value, so you can&#39;t accidentally pay to write the same string back.</p><p>Failures surface as a toast. If the whole dialog shows an error instead of the fields, the read failed — that&#39;s a network problem, not a problem with your name. Press <strong>Try again</strong>.</p><h2 id="binding-a-resolver" tabindex="-1">Binding a resolver <a class="header-anchor" href="#binding-a-resolver" aria-label="Permalink to &quot;Binding a resolver&quot;">​</a></h2><p>If the dialog says <em>&quot;This name has no resolver, so it can&#39;t store records yet&quot;</em>, the registry has no resolver recorded for your name and there is nowhere for records to go. Press <strong>Set a resolver</strong> to bind the default one.</p><p>Names registered through the app always have a resolver bound at mint time, so you&#39;ll only see this on a name whose resolver was removed, or one registered outside the app.</p><div class="danger custom-block"><p class="custom-block-title">Don&#39;t write to an unbound resolver</p><p>Writing records directly to a resolver that isn&#39;t bound in the registry appears to succeed — the transaction confirms and the resolver stores the data. But nobody resolving your name will ever look at that contract, so the records are invisible. Bind the resolver first, then write.</p></div><h2 id="reading-records" tabindex="-1">Reading records <a class="header-anchor" href="#reading-records" aria-label="Permalink to &quot;Reading records&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> namehash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;alice.arc&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> resolver</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> registry.read.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resolver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([node]);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> avatar</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> resolver.read.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([node, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;avatar&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span></code></pre></div><p>Every write emits an event, so records can also be indexed from logs:</p><table tabindex="0"><thead><tr><th>Event</th><th>Emitted by</th></tr></thead><tbody><tr><td><code>AddrChanged(node, a)</code></td><td><code>setAddr</code> (address form)</td></tr><tr><td><code>AddressChanged(node, coinType, newAddress)</code></td><td>both <code>setAddr</code> forms</td></tr><tr><td><code>TextChanged(node, key, value)</code></td><td><code>setText</code> — <code>key</code> is indexed</td></tr><tr><td><code>ContenthashChanged(node, hash)</code></td><td><code>setContenthash</code></td></tr><tr><td><code>NameChanged(node, name)</code></td><td><code>setName</code></td></tr></tbody></table><h2 id="records-are-public-and-unverified" tabindex="-1">Records are public and unverified <a class="header-anchor" href="#records-are-public-and-unverified" aria-label="Permalink to &quot;Records are public and unverified&quot;">​</a></h2><p>Two things to internalise before you fill in a profile.</p><p><strong>Everything is public and permanent.</strong> Records are plaintext on a public chain. There is no access control on reading, and overwriting a record does not erase the old value — the previous value stays in the transaction history forever. Don&#39;t put anything in a record you wouldn&#39;t publish.</p><p><strong>Nothing is verified.</strong> The resolver stores whatever string the owner writes. A <code>com.twitter</code> record claiming a handle is a <em>claim</em>, not proof — the protocol never checks it against X. Treat records shown next to a name the same way you&#39;d treat a self-reported bio.</p><p>The one exception is the reverse record, where the <code>verified</code> flag from the UniversalResolver does prove a round-trip. See <a href="/docs/protocol/resolving.html#reverse-resolution">Resolving .arc</a>.</p><h2 id="revert-reference" tabindex="-1">Revert reference <a class="header-anchor" href="#revert-reference" aria-label="Permalink to &quot;Revert reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Revert</th><th>Cause</th></tr></thead><tbody><tr><td><code>!auth</code></td><td>You are not the registry owner of the node. If you just received the name, call <code>reclaim</code> first.</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/guide/primary-name.html">Your primary name</a> — making apps display your name.</li><li><a href="/docs/guide/ownership.html">Ownership &amp; transfers</a> — reclaim, and why it matters.</li><li><a href="/docs/protocol/resolving.html">Resolving .arc</a> — reading records programmatically.</li></ul>`,48)])])}const g=s(r,[["render",n]]);export{k as __pageData,g as default};
